// Idempotency: use detected_at truncated to UTC day so the unique constraint
// (product_external_id, variant_external_id, detected_at) enforces one batch per day per item.
const now = new Date();
// Truncate to UTC day start so same-day events resolve to the same timestamp for dedup
const detectedAt = new Date(now);
detectedAt.setUTCHours(0, 0, 0, 0);

// Load quiet hours settings
const [settings] = await sql<{
  quiet_hours_start: string;
  quiet_hours_end: string;
  timezone: string;
}[]>`
  SELECT quiet_hours_start, quiet_hours_end, timezone
  FROM notification_settings
  LIMIT 1
`;

const quietStart = settings?.quiet_hours_start ?? "22:00";
const quietEnd = settings?.quiet_hours_end ?? "08:00";
const timezone = settings?.timezone ?? "America/New_York";

const scheduledSendAt = computeScheduledSendAt(now, quietStart, quietEnd, timezone);

// Atomic idempotent insert: ON CONFLICT on (product, variant, detected_at[day]) DO NOTHING
await sql`
  INSERT INTO notification_batches (
    product_external_id,
    variant_external_id,
    available_quantity_at_detection,
    status,
    entries_notified,
    detected_at,
    scheduled_send_at
  ) VALUES (
    ${productIdStr}::bigint,
    ${variantIdStr}::bigint,
    ${available},
    'pending',
    0,
    ${detectedAt},
    ${scheduledSendAt}
  )
  ON CONFLICT (product_external_id, variant_external_id, detected_at) DO NOTHING
`;
